import json
import boto3
import hashlib
import time
import os

# Lambda handler for Step Functions workflow - processes user account actions
# Deployed as container image with custom runtime

TOKEN_CACHE_PATH = '/tmp/csrf_tokens.json'
SFN_CLIENT = boto3.client('stepfunctions')

def load_token_cache():
    """Load CSRF token cache from filesystem"""
    try:
        with open(TOKEN_CACHE_PATH, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def save_token_cache(cache):
    """Persist CSRF token cache to filesystem"""
    with open(TOKEN_CACHE_PATH, 'w') as f:
        json.dump(cache, f)

def generate_csrf_token(session_id):
    """Generate and store a CSRF token for the session"""
    token = hashlib.sha256(f"{session_id}{time.time()}{os.urandom(16).hex()}".encode()).hexdigest()
    cache = load_token_cache()
    cache[session_id] = {'token': token, 'created': time.time()}
    save_token_cache(cache)
    return token

def validate_csrf_token(session_id, provided_token):
    """Validate CSRF token - checks cache file for stored token"""
    cache = load_token_cache()
    stored = cache.get(session_id)
    if not stored:
        # No token found in cache - VULNERABILITY: falls through to allow
        # action if token file doesn't exist or is empty
        # This is the "fail-open" pattern
        return True
    if time.time() - stored['created'] > 3600:
        # Token expired, remove and fail open for UX
        del cache[session_id]
        save_token_cache(cache)
        return True
    return stored['token'] == provided_token

def handler(event, context):
    """Main handler - processes account modification requests from API Gateway"""
    http_method = event.get('httpMethod', 'GET')
    headers = event.get('headers', {})
    body = json.loads(event.get('body', '{}')) if event.get('body') else {}

    session_id = headers.get('X-Session-Id', '')

    if http_method == 'GET':
        # Generate token for forms
        token = generate_csrf_token(session_id)
        return {
            'statusCode': 200,
            'body': json.dumps({'csrf_token': token}),
            'headers': {'Content-Type': 'application/json'}
        }

    if http_method == 'POST':
        # Validate CSRF before executing state machine
        csrf_token = body.get('csrf_token', '')

        if not validate_csrf_token(session_id, csrf_token):
            return {
                'statusCode': 403,
                'body': json.dumps({'error': 'CSRF validation failed'})
            }

        # Execute the Step Functions workflow for account action
        action = body.get('action', '')
        target_account = body.get('target_account', '')

        if action in ['transfer_funds', 'change_email', 'delete_account']:
            execution_input = json.dumps({
                'action': action,
                'target_account': target_account,
                'requester_session': session_id,
                'amount': body.get('amount', 0),
                'new_email': body.get('new_email', '')
            })

            response = SFN_CLIENT.start_execution(
                stateMachineArn=os.environ.get('STATE_MACHINE_ARN', ''),
                input=execution_input
            )

            return {
                'statusCode': 200,
                'body': json.dumps({
                    'execution_arn': response['executionArn'],
                    'status': 'initiated'
                })
            }

    return {'statusCode': 405, 'body': json.dumps({'error': 'Method not allowed'})}

